mapper.select:
select info.ISSUE_PARTY_ID, case when length(PROD_NAME)>180 then substr(PROD_NAME,1,180) else PROD_NAME end ACCOUNT_NAME, VDATE, PROD_ID ACCOUNT_ID, sysdate STATUS_DATE, info.STATUS, info.CREATE_USER, info.UPDATE_USER, info.ORG_CODE, info.DEPT_CODE CREATE_DEPT from chb_prd_baseinfo info where to_char(info.UPDATE_TIME,'yyyy-MM-dd') = to_char(#{statusDate,jdbcType=DATE},'yyyy-MM-dd') and info.PROFIT_TYPE='03' and info.fprod_id is null and info.ISSUING_STATUS='01'
and info.prod_id in
#{prodid}
